function values(t: Tensor): number[] {
  return Array.from(t.reshape([t.size]).data as ArrayLike<number>, Number);
}

function expectClose(actual: readonly number[], expected: readonly number[], tol = 1e-9): void {
  expect(actual.length).toBe(expected.length);
  for (let i = 0; i < expected.length; i++) {
    expect(Math.abs((actual[i] as number) - (expected[i] as number))).toBeLessThan(tol);
  }
}

function setWeights(layer: Conv2d | ConvTranspose2d, ref: Reference): void {
  const state = layer.stateDict();
  const weight = state.parameters["weight"];
  const bias = state.parameters["bias"];
  if (!weight || !bias) throw new Error("missing parameters");
  weight.data = ref.w;
  bias.data = ref.b;
  layer.loadStateDict(state);
}

function check(
  layer: Conv2d | ConvTranspose2d,
  input: number[],
  shape: number[],
  ref: Reference
): void {
  setWeights(layer, ref);
  const x = GradTensor.fromTensor(tensor(input, { dtype: "float64" }).reshape(shape), {
    requiresGrad: true,
  });
  const y = layer.forward(x);
  expect([...y.shape]).toEqual(ref.yShape);
  expectClose(values(y.tensor), ref.y);
  y.backward(tensor(ref.wgt, { dtype: "float64" }).reshape(ref.yShape));
  expectClose(values(x.grad as Tensor), ref.gx);
  expectClose(values(layer.weight.grad as Tensor), ref.gw);
  expectClose(values((layer.bias as GradTensor).grad as Tensor), ref.gb);
}

describe("NN-10: Conv2d paddingMode", () => {
  it.each(REF.pm.map((c) => [`${c.mode} ${JSON.stringify(c.cfg)}`, c] as const))(
    "%s matches torch",
    (_name, c) => {
      const layer = new Conv2d(2, 3, 3, {
        dtype: "float64",
        paddingMode: c.mode,
        ...(c.cfg.padding === undefined ? {} : { padding: c.cfg.padding }),
        ...(c.cfg.stride === undefined ? {} : { stride: c.cfg.stride }),
        ...(c.cfg.dilation === undefined ? {} : { dilation: c.cfg.dilation }),
      });
      check(layer, REF.x, [2, 2, 5, 4], c);
    }
  );

  it("rejects an unknown paddingMode", () => {
    const bad = "mirror" as unknown as "zeros";
    expect(() => new Conv2d(2, 3, 3, { paddingMode: bad })).toThrow(InvalidParameterError);
  });

  it("includes a non-default paddingMode in toString", () => {
    expect(new Conv2d(2, 3, 3, { padding: 1, paddingMode: "circular" }).toString()).toContain(
      "circular"
    );
  });
});

describe("NN-10: ConvTranspose2d groups", () => {
  it.each(REF.ct.map((c) => [JSON.stringify(c.cfg), c] as const))(
    "%s matches torch",
    (_name, c) => {
      const layer = new ConvTranspose2d(4, 6, 3, {
        dtype: "float64",
        groups: c.cfg.groups,
        ...(c.cfg.stride === undefined ? {} : { stride: c.cfg.stride }),
        ...(c.cfg.padding === undefined ? {} : { padding: c.cfg.padding }),
        ...(c.cfg.output_padding === undefined ? {} : { outputPadding: c.cfg.output_padding }),
      });
      expect([...layer.weight.shape]).toEqual(c.wShape);
      check(layer, REF.xt, [2, 4, 3, 3], c);
    }
  );

  it("rejects groups that do not divide the channel counts", () => {
    expect(() => new ConvTranspose2d(4, 6, 3, { groups: 4 })).toThrow(InvalidParameterError);
    expect(() => new ConvTranspose2d(4, 6, 3, { groups: 0 })).toThrow(InvalidParameterError);
  });
});
